{
  "status": "success",
  "tool": {
    "id": "biograph",
    "name": "Biograph Knowledge Graph",
    "description": "Query the Biograph Knowledge Graph for genes, proteins, diseases, variants, pathways, and drugs with their relationships",
    "category": "database",
    "parameters": [
      {
        "name": "query_type",
        "type": "select",
        "required": true,
        "description": "Type of query to perform",
        "options": [
          "entity-lookup",
          "search",
          "network"
        ]
      },
      {
        "name": "entity_type",
        "type": "select",
        "required": true,
        "description": "Type of biological entity",
        "options": [
          "gene",
          "protein",
          "disease",
          "variant",
          "pathway",
          "drug"
        ]
      },
      {
        "name": "entity_id",
        "type": "string",
        "required": false,
        "description": "Entity identifier (gene symbol, UniProt ID, MONDO ID, etc.)",
        "placeholder": "e.g., BRCA1, P38398, MONDO:0007254",
        "showWhen": {
          "parameter": "query_type",
          "value": [
            "entity-lookup",
            "network"
          ]
        }
      },
      {
        "name": "search_term",
        "type": "string",
        "required": false,
        "description": "Search term for finding entities",
        "placeholder": "e.g., breast cancer, alzheimer",
        "showWhen": {
          "parameter": "query_type",
          "value": "search"
        }
      },
      {
        "name": "limit",
        "type": "number",
        "required": false,
        "description": "Maximum number of results to return",
        "defaultValue": 50,
        "min": 1,
        "max": 1000,
        "showWhen": {
          "parameter": "query_type",
          "value": "search"
        }
      },
      {
        "name": "depth",
        "type": "number",
        "required": false,
        "description": "Network depth (number of relationship hops)",
        "defaultValue": 2,
        "min": 1,
        "max": 3,
        "showWhen": {
          "parameter": "query_type",
          "value": "network"
        }
      },
      {
        "name": "network_limit",
        "type": "number",
        "required": false,
        "description": "Maximum nodes in network (default: 50, max: 100)",
        "defaultValue": 50,
        "min": 1,
        "max": 100,
        "showWhen": {
          "parameter": "query_type",
          "value": "network"
        }
      },
      {
        "name": "relationship_types",
        "type": "string",
        "required": false,
        "description": "Comma-separated relationship types to include (e.g., ENCODES,AFFECTS)",
        "placeholder": "e.g., ENCODES,AFFECTS,ASSOCIATED_WITH",
        "showWhen": {
          "parameter": "query_type",
          "value": "network"
        }
      },
      {
        "name": "expand",
        "type": "select",
        "required": false,
        "description": "Expand all relationships (removes pagination limits)",
        "options": [
          "all"
        ],
        "showWhen": {
          "parameter": "query_type",
          "value": "entity-lookup"
        }
      }
    ],
    "executionMode": "instant",
    "version": "1.0.0",
    "author": "Bioinformatics Agent Team",
    "tags": [
      "genomics",
      "proteomics",
      "diseases",
      "pharmacology",
      "systems-biology",
      "clinical-genomics"
    ]
  },
  "timestamp": "2026-11-05T06:16:06.029Z"
}

